import {startTransition, useCallback, useMemo, useRef} from 'react'
import {useQuery, useQueryClient} from '@github-ui/react-query'

import {queries} from '../api'
import {REPO_SELECTION} from '../constants'
import type {EnablementRepo, RepoSelection} from '../types'

interface UseRepositoryDataParams {
  orgLogin: string
  assessmentNumber: number
  isOpen: boolean
  isSecretProtection: boolean
  repoSelection: RepoSelection
  debouncedFilterValue: string
}

interface UseRepositoryDataResult {
  reposById: Map<number, EnablementRepo>
  allCachedReposById: Map<number, EnablementRepo>
  totalRepoCount: number
  isLoading: boolean
  isError: boolean
  resetPreSelection: () => void
  applyPreSelection: (setSelectedRepoIds: (updater: (prev: Set<number>) => Set<number>) => void) => void
}

export function useRepositoryData({
  orgLogin,
  assessmentNumber,
  isOpen,
  isSecretProtection,
  repoSelection,
  debouncedFilterValue,
}: UseRepositoryDataParams): UseRepositoryDataResult {
  const queryClient = useQueryClient()
  const needsCsraRepos = !isSecretProtection && repoSelection === REPO_SELECTION.SELECTED

  const sraQuery = useQuery({
    ...queries.fetchRepos(orgLogin, assessmentNumber, debouncedFilterValue),
    enabled: isOpen && isSecretProtection,
  })
  const csraQuery = useQuery({
    ...queries.csraRepos(orgLogin, debouncedFilterValue),
    enabled: isOpen && needsCsraRepos,
  })
  const activeQuery = isSecretProtection ? sraQuery : csraQuery
  const reposData = activeQuery.data
  const isLoading = activeQuery.isLoading
  const isError = activeQuery.isError

  const cacheQueryKey = useMemo(
    () =>
      isSecretProtection
        ? ['secret-scanning', 'repositories', orgLogin, assessmentNumber]
        : ['code-security', 'csra-repos', orgLogin],
    [isSecretProtection, orgLogin, assessmentNumber],
  )

  // Merge all cached query responses so that repo metadata (especially committer IDs)
  // is preserved for selected repos even when they are hidden by the active filter.
  const allCachedReposById = useMemo(() => {
    const memo = new Map<number, EnablementRepo>()
    const cachedQueries = queryClient.getQueriesData<{repositories: EnablementRepo[]; totalCount: number}>({
      queryKey: cacheQueryKey,
    })
    for (const [, cachedData] of cachedQueries) {
      if (!cachedData) continue
      for (const repo of cachedData.repositories) memo.set(repo.id, repo)
    }
    if (reposData) {
      for (const repo of reposData.repositories) memo.set(repo.id, repo)
    }
    return memo
  }, [reposData, queryClient, cacheQueryKey])

  const reposById = useMemo(() => {
    const memo = new Map<number, EnablementRepo>()
    if (!reposData) return memo
    for (const repo of reposData.repositories) memo.set(repo.id, repo)
    return memo
  }, [reposData])

  const totalRepoCount = reposData?.totalCount || 0
  const initialCsraDataRef = useRef<typeof reposData | null>(null)

  const resetPreSelection = useCallback(() => {
    initialCsraDataRef.current = null
  }, [])

  const applyPreSelection = useCallback(
    (setSelectedRepoIds: (updater: (prev: Set<number>) => Set<number>) => void) => {
      if (isSecretProtection || !reposData || initialCsraDataRef.current) return
      initialCsraDataRef.current = reposData
      const ids = new Set(
        reposData.repositories
          .filter(repo => 'vulnerabilitiesFound' in repo && repo.vulnerabilitiesFound !== null)
          .map(repo => repo.id),
      )
      if (ids.size > 0) {
        startTransition(() => {
          setSelectedRepoIds(() => ids)
        })
      }
    },
    [isSecretProtection, reposData],
  )

  return {
    reposById,
    allCachedReposById,
    totalRepoCount,
    isLoading,
    isError,
    resetPreSelection,
    applyPreSelection,
  }
}
