import {InfoIcon, QuestionIcon} from '@primer/octicons-react'
import {AnchoredOverlay, Button, Link, Stack} from '@primer/react'
import {useState} from 'react'
import styles from './InfoButton.module.css'

interface InfoButtonProps {
  ariaLabel: string
  title: string
  children?: React.ReactNode
}

interface InfoButtonDescriptionProps {
  role?: string
  ariaLabel?: string
  children: React.ReactNode
}

interface InfoButtonLinkProps {
  href: string
  ariaLabel: string
  children: React.ReactNode
}

export function InfoButton({ariaLabel, title, children}: InfoButtonProps) {
  const [open, setOpen] = useState(false)

  return (
    <div className={styles.wrapper}>
      <AnchoredOverlay
        open={open}
        onOpen={() => setOpen(true)}
        onClose={() => setOpen(false)}
        focusZoneSettings={{disabled: true}}
        preventOverflow={false}
        overlayProps={{role: 'dialog', 'aria-label': title}}
        renderAnchor={props => (
          <Button
            {...props}
            size="small"
            alignContent="center"
            variant="invisible"
            leadingVisual={<InfoIcon size="small" />}
            aria-label={ariaLabel}
          />
        )}
        align="center"
        width="medium"
        variant={{narrow: 'fullscreen', regular: 'anchored'}}
      >
        <Stack direction="vertical" padding="normal">
          <h5>{title}</h5>
          {children}
        </Stack>
      </AnchoredOverlay>
    </div>
  )
}

InfoButton.Description = function InfoButtonDescription({role, ariaLabel, children}: InfoButtonDescriptionProps) {
  return (
    <p className={styles.plainText} role={role} aria-label={ariaLabel || undefined}>
      {children}
    </p>
  )
}

InfoButton.Link = function InfoButtonLink({href, ariaLabel, children}: InfoButtonLinkProps) {
  return (
    <div className={styles.buttonRow}>
      <QuestionIcon size="small" className={styles.buttonContent} />
      <Link className={styles.linkedText} href={href} inline aria-label={ariaLabel}>
        {children}
      </Link>
    </div>
  )
}
