import {Link} from '@primer/react'
import {REPO_SELECTION} from '../../../constants'
import type {CostDisplayValues, RepoSelection} from '../../../types'
import {CostSummaryBox} from './CostSummaryBox'
import {SettingsAdjustmentNote} from '../SettingsAdjustmentNote'

interface ReviewProps {
  totalCostDisplay: string
  org: string
  repoSelection: RepoSelection
  isSecretProtection: boolean
  isMetered: boolean
  productName: string
  costDisplayValues: CostDisplayValues
}

export function Review({
  totalCostDisplay,
  org,
  repoSelection,
  isSecretProtection,
  isMetered,
  productName,
  costDisplayValues,
}: ReviewProps) {
  const {licenseCount, repositoryCountText, perLicenseCost} = costDisplayValues
  const isAllRepos = repoSelection === REPO_SELECTION.ALL
  const reposToEnableText = isAllRepos ? 'all existing and future repositories' : 'selected repositories'

  const confirmationText = isSecretProtection
    ? `Would you like to enable ${productName} with secret scanning alerts and push protection for`
    : `Would you like to enable ${productName} with code scanning and Copilot Autofix for`

  return (
    <>
      <p>
        {confirmationText} {reposToEnableText}?
      </p>
      {isAllRepos && <SettingsAdjustmentNote org={org} />}
      {(isSecretProtection || isMetered) && (
        <CostSummaryBox
          totalCostDisplay={totalCostDisplay}
          licenseCount={licenseCount}
          repositoryCountText={repositoryCountText}
          perLicenseCost={perLicenseCost}
          variant="review"
          productName={productName}
        />
      )}
      {(isSecretProtection || isMetered) && (
        <span className="fgColor-muted f-small lh-default">
          You will be charged for additional committers in your next billing cycle.{' '}
          <Link href={`/organizations/${org}/settings/billing`} inline>
            Review billing information
          </Link>{' '}
          for more details.
        </span>
      )}
    </>
  )
}
