import {startTransition, useCallback, useState} from 'react'
import {REPO_SELECTION} from '../constants'
import type {DialogStep, RepoSelection} from '../types'

export function useDialogNavigation() {
  const [repoSelection, setRepoSelection] = useState<RepoSelection>(REPO_SELECTION.ALL)
  const [currentStep, setCurrentStep] = useState<DialogStep>('cost-estimation')
  const [isTransitioning, setIsTransitioning] = useState(false)

  const handleBackClick = useCallback(() => {
    setCurrentStep(prev => {
      if (prev === 'review')
        return repoSelection === REPO_SELECTION.SELECTED ? 'repository-selection' : 'cost-estimation'
      if (prev === 'repository-selection') return 'cost-estimation'
      return prev
    })
  }, [repoSelection])

  const handleSelectRepositoriesClick = useCallback(() => {
    setIsTransitioning(true)
    setCurrentStep('repository-selection')
    startTransition(() => {
      setIsTransitioning(false)
    })
  }, [])

  const handleReviewAndEnableClick = useCallback(() => {
    setCurrentStep('review')
  }, [])

  const resetNavigation = useCallback(() => {
    setCurrentStep('cost-estimation')
    setRepoSelection(REPO_SELECTION.ALL)
    setIsTransitioning(false)
  }, [])

  return {
    repoSelection,
    setRepoSelection,
    currentStep,
    isTransitioning,
    handleBackClick,
    handleSelectRepositoriesClick,
    handleReviewAndEnableClick,
    resetNavigation,
  }
}
