import {useAnalytics, useClickAnalytics} from '@github-ui/use-analytics'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Icon} from '@primer/octicons-react'
import {XIcon} from '@primer/octicons-react'
import {Banner, Button, IconButton, Label, type LabelColorOptions, Link, Stack} from '@primer/react'
import {
  type ComponentPropsWithoutRef,
  type CSSProperties,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useState,
} from 'react'

import upsellBgDark from './assets/upsell-bg-dark.svg'
import upsellBgDarkMobile from './assets/upsell-bg-dark-mobile.svg'
import upsellBgLight from './assets/upsell-bg-light.svg'
import upsellBgLightMobile from './assets/upsell-bg-light-mobile.svg'
import styles from './UpsellBanner.module.css'

interface UpsellBannerAnalyticsProps {
  group: string
  location: string
  category: string
  primaryCtaAction: string
  secondaryCtaAction?: string
  dismissAction?: string
  userId: string
  enterpriseId?: string
  organizationId?: string
  [key: string]: string | undefined // add extensibility to payload, can be any kv pair
}

interface UpsellBannerBaseProps extends ComponentPropsWithoutRef<'aside'> {
  heading: string
  description: ReactNode
  primaryActionText?: string
  primaryActionHref?: string
  primaryActionOnClick?: () => void
  /** When true, disables the primary action button. Has no effect when the primary action renders as a link. */
  primaryActionDisabled?: boolean
  secondaryActionText?: string
  secondaryActionHref?: string
  secondaryActionOnClick?: () => void
  secondaryActionIcon?: Icon
  /** When set, the secondary action renders as a link-styled button that POSTs to this path via verifiedFetch. */
  secondaryActionPostPath?: string
  /** Controls behavior after the POST fires. 'dismiss' hides the banner; 'click' keeps it visible. Defaults to 'click'. */
  secondaryActionPostBehavior?: 'click' | 'dismiss'
  /**
   * When provided alongside `secondaryActionPostPath`, clicking the secondary action replaces the
   * banner in place with an inline info flash. The swap is ephemeral, client-side only state: it
   * adds no backend record and does not persist across reloads. The flash takes precedence over
   * `secondaryActionPostBehavior`. Use it to confirm a reversible action (e.g. "Remind me later")
   * while the underlying banner stays hidden via whatever snooze `secondaryActionPostPath` persists.
   */
  secondaryActionFlash?: {
    /** Flash heading, used as the Banner title and accessible name. */
    title: string
    /** Supplemental body text. If `linkText` appears within it, that phrase becomes a link to `linkHref`. */
    description?: string
    /** Substring of `description` to render as a link. */
    linkText?: string
    /** Destination for the linked phrase. The link navigates directly (no dismiss-and-redirect). */
    linkHref?: string
    /** Analytics action emitted when the flash link is clicked. */
    linkAnalyticsAction?: string
  }
  productShotLight?: string
  productShotDark?: string
  productShotAltText?: string
  productShotAltDarkText?: string
  showProductShotBackground?: boolean
  /**
   * Configures the desktop layout balance between content and product shot.
   * compact: 5 columns, medium: 6 columns, large: 7 columns (out of 10 total).
   */
  contentLayout?: 'compact' | 'medium' | 'large'
  headingLevel?: 'h2' | 'h3' | 'h4'
  analytics?: UpsellBannerAnalyticsProps
  /** Optional pill label rendered in the top-left corner of the banner. */
  label?: {
    text: string
    variant?: LabelColorOptions
  }
}

type DismissibleProps =
  | {
      dismissible?: false
      storageKey?: never
      dismissPath?: never
    }
  | {
      dismissible: true
      storageKey: string
      dismissPath?: string
    }

export type UpsellBannerProps = UpsellBannerBaseProps & DismissibleProps

const contentLayoutToColumns = {
  compact: 5,
  medium: 6,
  large: 7,
} as const

export function UpsellBanner({
  heading,
  description,
  primaryActionText,
  primaryActionHref,
  primaryActionOnClick,
  primaryActionDisabled = false,
  secondaryActionText,
  secondaryActionHref,
  secondaryActionOnClick,
  secondaryActionIcon,
  secondaryActionPostPath,
  secondaryActionPostBehavior = 'click',
  secondaryActionFlash,
  productShotLight,
  productShotDark,
  productShotAltText = '',
  productShotAltDarkText = '',
  showProductShotBackground = true,
  className,
  dismissible = false,
  storageKey,
  dismissPath,
  headingLevel: HeadingTag = 'h2',
  contentLayout = 'medium',
  analytics,
  label,
  ...props
}: UpsellBannerProps) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const {sendAnalyticsEvent} = useAnalytics()
  const headingId = useId()
  const [isVisible, setIsVisible] = useState(() => {
    if (typeof window !== 'undefined' && storageKey) {
      const wasDismissed = sessionStorage.getItem(storageKey)
      return !wasDismissed
    }
    return true
  })
  const [showSecondaryActionFlash, setShowSecondaryActionFlash] = useState(false)

  const hasPrimaryAction = primaryActionText && (primaryActionHref || primaryActionOnClick)
  const hasSecondaryAction =
    secondaryActionText && (secondaryActionHref || secondaryActionOnClick || secondaryActionPostPath)
  const hasActions = hasPrimaryAction || hasSecondaryAction
  const hasProductShot = productShotLight || productShotDark
  const contentColumns = contentLayoutToColumns[contentLayout]

  // If only one image is provided, use it for both themes
  const lightImage = productShotLight ?? productShotDark
  const darkImage = productShotDark ?? productShotLight
  const hasBothThemes = productShotLight && productShotDark

  const buildAnalyticsPayload = useCallback(
    (action?: string) => {
      if (!analytics || !action) return

      const {
        group,
        primaryCtaAction,
        secondaryCtaAction,
        dismissAction,
        category,
        location,
        userId,
        organizationId,
        enterpriseId,
        ...extraAnalytics
      } = analytics

      return {
        category,
        action,
        label: group,
        location,
        userId,
        ...(organizationId && {organizationId}),
        ...(enterpriseId && {enterpriseId}),
        ...extraAnalytics,
      }
    },
    [analytics],
  )

  useEffect(() => {
    if (!isVisible) return

    const payload = buildAnalyticsPayload('visible')
    if (payload) {
      sendAnalyticsEvent('analytics.visible', undefined, payload)
    }
  }, [isVisible, sendAnalyticsEvent, buildAnalyticsPayload])

  const handleActionClick = (analyticsAction?: string, onClick?: () => void) => {
    return () => {
      const payload = buildAnalyticsPayload(analyticsAction)
      if (payload) {
        sendClickAnalyticsEvent(payload)
      }
      onClick?.()
    }
  }

  const handleDismiss = () => {
    const payload = buildAnalyticsPayload(analytics?.dismissAction)
    if (payload) {
      sendClickAnalyticsEvent(payload)
    }
    // Persist dismissal server-side if a dismiss endpoint is provided
    if (dismissPath) {
      void verifiedFetch(dismissPath, {method: 'POST'})
    }
    setIsVisible(false)
    if (typeof window !== 'undefined' && storageKey) {
      const key = storageKey
      sessionStorage.setItem(key, 'true')
    }
  }

  const handleSecondaryPostAction = () => {
    void verifiedFetch(secondaryActionPostPath!, {method: 'POST'})
    if (secondaryActionFlash) {
      // Swap the banner in place for an ephemeral inline flash. The POST above still persists the
      // server-side snooze, so a refresh shows a clean page and this flash never reappears.
      setShowSecondaryActionFlash(true)
    } else if (secondaryActionPostBehavior === 'dismiss') {
      setIsVisible(false)
      if (typeof window !== 'undefined' && storageKey) {
        const key = storageKey
        sessionStorage.setItem(key, 'true')
      }
    }
    secondaryActionOnClick?.()
  }

  const renderFlashDescription = (flash: NonNullable<UpsellBannerProps['secondaryActionFlash']>): ReactNode => {
    const {description: flashDescription, linkText, linkHref, linkAnalyticsAction} = flash
    if (!flashDescription) {
      return undefined
    }
    if (!linkText || !linkHref) {
      return flashDescription
    }
    const linkStart = flashDescription.indexOf(linkText)
    if (linkStart === -1) {
      return flashDescription
    }
    const before = flashDescription.slice(0, linkStart)
    const after = flashDescription.slice(linkStart + linkText.length)
    return (
      <>
        {before}
        <Link inline href={linkHref} onClick={handleActionClick(linkAnalyticsAction)}>
          {linkText}
        </Link>
        {after}
      </>
    )
  }

  const backgroundVars =
    showProductShotBackground && hasProductShot
      ? ({
          '--upsell-bg-light-mobile': `url(${upsellBgLightMobile})`,
          '--upsell-bg-dark-mobile': `url(${upsellBgDarkMobile})`,
          '--upsell-bg-light': `url(${upsellBgLight})`,
          '--upsell-bg-dark': `url(${upsellBgDark})`,
        } as CSSProperties)
      : {}

  if (!isVisible) {
    return null
  }

  if (showSecondaryActionFlash && secondaryActionFlash) {
    return (
      <Banner
        ref={node => {
          // The focused secondary action button is unmounted when the banner is
          // replaced by this flash. Move focus into the flash so keyboard and
          // screen reader users are not dropped to the document body and the
          // flash's accessible name is announced.
          node?.focus()
        }}
        tabIndex={-1}
        title={secondaryActionFlash.title}
        variant="info"
        className={className}
        hideTitle
        description={renderFlashDescription(secondaryActionFlash)}
        onDismiss={() => setIsVisible(false)}
      />
    )
  }

  return (
    <aside
      className={`${styles.container} ${!hasProductShot ? styles.containerFullWidth : ''} ${showProductShotBackground && hasProductShot ? styles.productShotWithBackground : ''} ${className ?? ''}`}
      aria-labelledby={headingId}
      style={{
        '--content-columns': contentColumns,
        '--media-columns': 10 - contentColumns,
        ...backgroundVars,
      }}
      {...props}
    >
      <div className={styles.content}>
        {label ? (
          <div className={styles.label}>
            <Label variant={label.variant ?? 'default'}>{label.text}</Label>
          </div>
        ) : null}
        <HeadingTag id={headingId} className={styles.heading}>
          {heading}
        </HeadingTag>
        <p className={styles.description}>{description}</p>
        {hasActions ? (
          <Stack direction="horizontal" gap="normal" wrap="wrap" align="center" className={styles.actions}>
            {hasPrimaryAction ? (
              primaryActionHref ? (
                <Button
                  as="a"
                  href={primaryActionHref}
                  variant="primary"
                  className={styles.primaryButton}
                  onClick={handleActionClick(analytics?.primaryCtaAction)}
                >
                  {primaryActionText}
                </Button>
              ) : (
                <Button
                  variant="primary"
                  className={styles.primaryButton}
                  onClick={handleActionClick(analytics?.primaryCtaAction, primaryActionOnClick)}
                  disabled={primaryActionDisabled}
                >
                  {primaryActionText}
                </Button>
              )
            ) : null}
            {hasSecondaryAction ? (
              secondaryActionHref ? (
                <Link
                  href={secondaryActionHref}
                  onClick={handleActionClick(analytics?.secondaryCtaAction, secondaryActionOnClick)}
                >
                  {secondaryActionText}
                </Link>
              ) : secondaryActionPostPath ? (
                <Link as="button" onClick={handleActionClick(analytics?.secondaryCtaAction, handleSecondaryPostAction)}>
                  {secondaryActionText}
                </Link>
              ) : (
                <Button
                  onClick={handleActionClick(analytics?.secondaryCtaAction, secondaryActionOnClick)}
                  variant="invisible"
                  leadingVisual={secondaryActionIcon}
                >
                  {secondaryActionText}
                </Button>
              )
            ) : null}
          </Stack>
        ) : null}
      </div>
      {hasProductShot ? (
        <div className={styles.productShot} aria-hidden="true">
          {hasBothThemes ? (
            <>
              <div className={styles.lightOnly}>
                <img src={lightImage} alt={productShotAltText} />
              </div>
              <div className={styles.darkOnly}>
                <img src={darkImage} alt={productShotAltDarkText || productShotAltText} />
              </div>
            </>
          ) : (
            <img src={lightImage} alt={productShotAltText} />
          )}
        </div>
      ) : null}
      {dismissible ? (
        <div className={styles.dismissButton}>
          <IconButton aria-label="Dismiss banner" icon={XIcon} size="small" onClick={handleDismiss} />
        </div>
      ) : null}
    </aside>
  )
}
