import type {ReactNode} from 'react'
import {Button, Stack} from '@primer/react'
import {CopilotIcon} from '@primer/octicons-react'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {openSecurityAssessmentCopilotChat} from '../../utils/copilot-chat-helpers'
import {RiskAssessmentBanner} from './RiskAssessmentBanner'
import {StartTrialActions} from '../shared/StartTrialActions'
import {useGhasTrial} from '../../hooks/use-ghas-trial'
import noLeaksBannerDay from '../../assets/secret-scanning-no_leaks_banner--day.png'
import noLeaksBannerNight from '../../assets/secret-scanning-no_leaks_banner--night.png'

const NO_LEAKS_MESSAGE = "Great work, no secrets found in your organization's repositories."

type TrialActionsProps =
  | {
      /**
       * When provided AND the GHAS trial flag indicates the org can start a
       * trial, render `Start Trial` as the primary action instead of the
       * default enable buttons. Overflow menu items are optional and only shown
       * when present.
       */
      onStartTrial: () => void
      trialOverflowMenuItems?: ReactNode
    }
  | {onStartTrial?: undefined; trialOverflowMenuItems?: undefined}

type NoLeaksBannerProps = {
  enableButtons: ReactNode
} & TrialActionsProps

export function NoLeaksBanner({enableButtons, trialOverflowMenuItems, onStartTrial}: NoLeaksBannerProps) {
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showCopilotAssist = useFeatureFlag('risk_assessment_copilot_assistive')
  const {canStartTrial} = useGhasTrial()
  const showTrialActions = canStartTrial && onStartTrial != null

  return (
    <RiskAssessmentBanner
      title={NO_LEAKS_MESSAGE}
      description="Stop leaks before they happen with Secret Protection."
      analyticsVisible={{
        category: 'no-secrets-banner',
        action: 'visible',
        group: 'expand',
        location: 'security-assessment-post-scan',
      }}
      images={{day: noLeaksBannerDay, night: noLeaksBannerNight}}
      actions={
        <Stack direction="horizontal" align="center" gap="condensed">
          {showTrialActions ? (
            <StartTrialActions onStartTrial={onStartTrial} overflowMenuItems={trialOverflowMenuItems} />
          ) : (
            enableButtons
          )}
          {showCopilotAssist && !showTrialActions && (
            <Button variant="invisible" leadingVisual={CopilotIcon} onClick={openSecurityAssessmentCopilotChat}>
              Ask Copilot
            </Button>
          )}
        </Stack>
      }
    />
  )
}

export function NoLeaksSuccessBanner() {
  return (
    <RiskAssessmentBanner
      title={NO_LEAKS_MESSAGE}
      description="Treat yourself — you did good today. ✨"
      images={{day: noLeaksBannerDay, night: noLeaksBannerNight}}
      dismissible
    />
  )
}
