import {Button} from '@primer/react'
import Pluralize from 'pluralize'

interface CostSummary {
  totalCost: string
  licenseCount: number
  productName: string
}

interface FooterProps {
  primaryLabel: string
  primaryLoading: boolean
  primaryDisabled: boolean
  primaryAction: () => void
  selectedCount?: number
  costSummary?: CostSummary
  onClose: () => void
}

export function Footer({
  primaryLabel,
  primaryLoading,
  primaryDisabled,
  primaryAction,
  selectedCount,
  costSummary,
  onClose,
}: FooterProps) {
  return (
    <div
      className={`d-flex ${costSummary ? 'flex-justify-between flex-items-center' : 'flex-justify-end gap-2'} tmp-p-3 border-top`}
    >
      {costSummary && (
        <div>
          <div data-testid="total-cost" className="text-semibold">
            Total cost: {costSummary.totalCost} / month
          </div>
          <div data-testid="license-count" className="color-fg-muted text-small">
            {costSummary.licenseCount} {costSummary.productName} {Pluralize('license', costSummary.licenseCount, false)}{' '}
            required
          </div>
        </div>
      )}
      {costSummary ? (
        <div className="d-flex flex-justify-end gap-2">
          <Button onClick={onClose}>Cancel</Button>
          <Button
            variant="primary"
            onClick={primaryAction}
            loading={primaryLoading}
            disabled={primaryDisabled}
            count={selectedCount || undefined}
          >
            {primaryLabel}
          </Button>
        </div>
      ) : (
        <>
          <Button onClick={onClose}>Cancel</Button>
          <Button
            variant="primary"
            onClick={primaryAction}
            loading={primaryLoading}
            disabled={primaryDisabled}
            count={selectedCount || undefined}
          >
            {primaryLabel}
          </Button>
        </>
      )}
    </div>
  )
}
