import type {ReactNode} from 'react'
import {CopilotIcon} from '@primer/octicons-react'
import {Button, Link} from '@primer/react'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {openSecurityAssessmentCopilotChat} from '../../utils/copilot-chat-helpers'
import {EnablementBanner} from '../shared/EnablementBanner'
import {StartTrialActions} from '../shared/StartTrialActions'
import {useGhasTrial} from '../../hooks/use-ghas-trial'

type TrialActionsProps =
  | {
      /**
       * When provided AND the GHAS trial flag indicates the org can start a
       * trial, render `Start Trial` as the primary action instead of the
       * default Ask Copilot + enable actions. Overflow menu items are optional
       * and only shown when present.
       */
      onStartTrial: () => void
      trialOverflowMenuItems?: ReactNode
    }
  | {onStartTrial?: undefined; trialOverflowMenuItems?: undefined}

type AssessmentResultBannerProps = {
  enableButtons: ReactNode
} & TrialActionsProps

export function AssessmentResultBanner({
  enableButtons,
  trialOverflowMenuItems,
  onStartTrial,
}: AssessmentResultBannerProps) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showCopilotAssist = useFeatureFlag('risk_assessment_copilot_assistive')
  const {canStartTrial} = useGhasTrial()
  const showTrialActions = canStartTrial && onStartTrial != null

  return (
    <EnablementBanner
      title="Protect your repositories from future leaks with Secret Protection"
      analyticsVisible={{
        category: 'protect-repos-banner',
        action: 'visible',
        group: 'expand',
        location: 'security-assessment-post-scan',
      }}
      description={
        <>
          Have questions about Secret Protection?{' '}
          <Link
            inline
            href="https://github.com/security/advanced-security/secret-protection/contact-sales?utm_campaign=GHAS_secret_risk_assessment_contact_utmroutercampaign"
            onClick={() =>
              sendClickAnalyticsEvent({
                location: 'security-assessment-post-scan',
                category: 'results-banner',
                action: 'talk-to-someone',
                tag: 'link',
                group: 'expand',
              })
            }
          >
            Talk to someone from GitHub
          </Link>{' '}
          or{' '}
          <Link
            inline
            href="https://www.youtube.com/watch?v=vMhDkt5JNN0"
            onClick={() =>
              sendClickAnalyticsEvent({
                location: 'security-assessment-post-scan',
                category: 'results-banner',
                action: 'watch-demo',
                tag: 'link',
                group: 'expand',
              })
            }
          >
            watch a demo
          </Link>
          .
        </>
      }
      actions={
        showTrialActions ? (
          <>
            {showCopilotAssist && (
              <Button
                variant="invisible"
                leadingVisual={CopilotIcon}
                onClick={() => {
                  openSecurityAssessmentCopilotChat()
                }}
              >
                Ask Copilot
              </Button>
            )}
            <StartTrialActions onStartTrial={onStartTrial} overflowMenuItems={trialOverflowMenuItems} />
          </>
        ) : (
          <>
            {showCopilotAssist && (
              <Button
                variant="invisible"
                leadingVisual={CopilotIcon}
                onClick={() => {
                  openSecurityAssessmentCopilotChat()
                }}
              >
                Ask Copilot
              </Button>
            )}
            {enableButtons}
          </>
        )
      }
    />
  )
}
