import {useState, useMemo, useCallback, useRef, useEffect} from 'react'
import pluralize from 'pluralize'
import {Banner, Checkbox, FormControl, Link, Spinner, Truncate} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {AlertIcon, OrganizationIcon, RepoIcon, RepoLockedIcon} from '@primer/octicons-react'
import {Filter} from '@github-ui/filter'
import type {FilterQuery, SubmitEvent} from '@github-ui/filter-core'
import {PickerListBody} from '@github-ui/filter-picker'
import {getAllStaticProviders} from '@github-ui/repos-filter/providers'
import type {PickerRepository} from '@github-ui/repos-picker'
import {usePrefersReducedMotion} from '@github-ui/use-prefers-reduced-motion'
import {useDebounce} from '@github-ui/use-debounce'
import {useQuery} from '@github-ui/react-query'

import {queries} from '../../../api'
import {MAX_CODE_SECURITY_REPOS, SUPPORTED_LANGUAGES_URL} from '../../../constants'
import styles from './RepositorySelection.module.css'

function getRepoName(repo: PickerRepository) {
  return (
    <Truncate title={repo.name} className={`text-semibold ${styles.repositoryName}`}>
      {repo.name}
    </Truncate>
  )
}

function getRepoIcon(repo: PickerRepository) {
  switch (repo.visibility) {
    case 'private':
      return <RepoLockedIcon size={16} />
    case 'internal':
      return <OrganizationIcon size={16} />
    default:
      return <RepoIcon size={16} />
  }
}

interface RepositorySelectionProps {
  selectedRepoIds: Set<number>
  onSelectionChange: (selectedIds: Set<number>) => void
  orgLogin: string
  showSelectionWarning: boolean
}

export function RepositorySelection({
  selectedRepoIds,
  onSelectionChange,
  orgLogin,
  showSelectionWarning,
}: RepositorySelectionProps) {
  const [inputValue, setInputValue] = useState('')
  const [debouncedFilterValue, setDebouncedFilterValue] = useState('')
  const warningBannerRef = useRef<HTMLDivElement>(null)
  const prefersReducedMotion = usePrefersReducedMotion()
  const providers = useMemo(() => getAllStaticProviders(), [])

  // Normalize the filter value once for consistent use in query and UI
  const normalizedQuery = debouncedFilterValue.trim() || undefined

  // Query for filtered results (used for display)
  const {data, isLoading, isError} = useQuery(queries.codeSecurityEligibleRepos(orgLogin, normalizedQuery))

  const eligibleRepos = useMemo(() => data?.eligibleRepos ?? [], [data?.eligibleRepos])
  const totalEligibleRepoCount = data?.totalEligibleRepoCount ?? 0

  const debouncedSetFilterQuery = useDebounce((value: string) => setDebouncedFilterValue(value), 300)

  const handleFilterChange = useCallback(
    (value: string) => {
      setInputValue(value)
      debouncedSetFilterQuery(value)
    },
    [debouncedSetFilterQuery],
  )

  const handleFilterSubmit = useCallback((query: FilterQuery, _eventType: SubmitEvent) => {
    setInputValue(query.raw)
    setDebouncedFilterValue(query.raw)
  }, [])

  const isOverLimit = selectedRepoIds.size > MAX_CODE_SECURITY_REPOS
  const overLimitCount = selectedRepoIds.size - MAX_CODE_SECURITY_REPOS

  useEffect(() => {
    if ((showSelectionWarning || isOverLimit) && warningBannerRef.current) {
      warningBannerRef.current.scrollIntoView({behavior: prefersReducedMotion ? 'auto' : 'smooth', block: 'nearest'})
    }
  }, [showSelectionWarning, isOverLimit, prefersReducedMotion])

  const displayRepos = useMemo(() => {
    if (isLoading || isError) return []
    if (!normalizedQuery) return eligibleRepos
    // When filtering, partition selected repos to the top while preserving original order within each group
    const selected: PickerRepository[] = []
    const unselected: PickerRepository[] = []
    for (const repo of eligibleRepos) {
      if (selectedRepoIds.has(repo.id)) {
        selected.push(repo)
      } else {
        unselected.push(repo)
      }
    }
    return [...selected, ...unselected]
  }, [isLoading, isError, eligibleRepos, normalizedQuery, selectedRepoIds])

  const selectedRepos = useMemo(() => {
    return displayRepos.filter(repo => selectedRepoIds.has(repo.id))
  }, [displayRepos, selectedRepoIds])

  const hiddenSelectedCount = useMemo(() => {
    const visibleIds = new Set(displayRepos.map(r => r.id))
    return Array.from(selectedRepoIds).filter(id => !visibleIds.has(id)).length
  }, [selectedRepoIds, displayRepos])

  const selectionLabel = useMemo(() => {
    const selectedCount = normalizedQuery ? selectedRepos.length : selectedRepoIds.size
    return `${selectedCount} of ${totalEligibleRepoCount} ${pluralize('repository', totalEligibleRepoCount)} selected`
  }, [normalizedQuery, selectedRepos.length, selectedRepoIds.size, totalEligibleRepoCount])

  // Compute select all checkbox state
  const isSelectAllChecked = useMemo(() => {
    if (eligibleRepos.length === 0) return false
    return eligibleRepos.every(repo => selectedRepoIds.has(repo.id))
  }, [eligibleRepos, selectedRepoIds])

  const isSelectAllIndeterminate = useMemo(() => {
    if (eligibleRepos.length === 0) return false
    const someSelected = eligibleRepos.some(repo => selectedRepoIds.has(repo.id))
    const allSelected = eligibleRepos.every(repo => selectedRepoIds.has(repo.id))
    return someSelected && !allSelected
  }, [eligibleRepos, selectedRepoIds])

  const handleSelectAll = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const visibleIds = new Set(eligibleRepos.map(r => r.id))
      const hiddenSelections = Array.from(selectedRepoIds).filter(id => !visibleIds.has(id))

      if (event.target.checked) {
        // Select all visible repos (keep hidden selections from other filter contexts)
        onSelectionChange(new Set([...hiddenSelections, ...eligibleRepos.map(r => r.id)]))
      } else if (normalizedQuery) {
        // When filtered, only deselect visible repos (preserve selections from other filter contexts)
        onSelectionChange(new Set(hiddenSelections))
      } else {
        // When unfiltered, deselect everything (including repos beyond the visible page)
        onSelectionChange(new Set())
      }
    },
    [eligibleRepos, selectedRepoIds, normalizedQuery, onSelectionChange],
  )

  const handleItemSelectionChange = useCallback(
    (repos: PickerRepository[]) => {
      const visibleIds = new Set(eligibleRepos.map(r => r.id))
      const hiddenSelections = Array.from(selectedRepoIds).filter(id => !visibleIds.has(id))
      onSelectionChange(new Set([...hiddenSelections, ...repos.map(r => r.id)]))
    },
    [eligibleRepos, selectedRepoIds, onSelectionChange],
  )

  const blankView = useMemo(() => {
    if (isLoading) {
      return (
        <Blankslate>
          <Blankslate.Visual>
            <Spinner size="medium" />
          </Blankslate.Visual>
          <Blankslate.Description>Loading repositories...</Blankslate.Description>
        </Blankslate>
      )
    }
    if (isError) {
      return (
        <Blankslate>
          <Blankslate.Visual>
            <AlertIcon className="fgColor-danger" />
          </Blankslate.Visual>
          <Blankslate.Heading>We couldn&apos;t load the repositories</Blankslate.Heading>
          <Blankslate.Description>Try again, or if the problem persists, contact support.</Blankslate.Description>
        </Blankslate>
      )
    }
    if (eligibleRepos.length === 0) {
      return (
        <Blankslate>
          <Blankslate.Heading>No repositories found</Blankslate.Heading>
          <Blankslate.Description>
            {normalizedQuery ? 'Try a different search query.' : 'No eligible repositories for assessment.'}
          </Blankslate.Description>
        </Blankslate>
      )
    }
    return null
  }, [isLoading, isError, eligibleRepos.length, normalizedQuery])

  return (
    <div className={styles.repositorySelectionContainer}>
      {!isLoading && !isError && (
        <p className="fgColor-muted f6 tmp-px-3 tmp-pt-3 mb-0">
          Code Security scans up to {MAX_CODE_SECURITY_REPOS} private or internal repositories with one or more{' '}
          <Link inline href={SUPPORTED_LANGUAGES_URL}>
            supported languages
          </Link>
          . You have {totalEligibleRepoCount} eligible {pluralize('repository', totalEligibleRepoCount)}.
        </p>
      )}
      <div className={styles.stickyHeader}>
        <div className={styles.filterContainer}>
          <Filter
            id="code-security-repository-filter"
            label="Filter repositories"
            variant="input"
            filterValue={inputValue}
            onChange={handleFilterChange}
            onSubmit={handleFilterSubmit}
            providers={providers}
            context={{org: orgLogin}}
          />
        </div>
        {showSelectionWarning && (
          <div ref={warningBannerRef} className={styles.warningBanner}>
            <Banner variant="warning" title="Selection required" hideTitle>
              You must select at least one repository to scan with Code Security.
            </Banner>
          </div>
        )}
        {isOverLimit && (
          <div ref={warningBannerRef} className={styles.warningBanner}>
            <Banner variant="warning" title="Selection limit exceeded" hideTitle>
              You can only select {MAX_CODE_SECURITY_REPOS} repositories, deselect {overLimitCount}{' '}
              {pluralize('repository', overLimitCount)} to start scan.
            </Banner>
          </div>
        )}
        {!isLoading && !isError && eligibleRepos.length > 0 && (
          <FormControl className={styles.selectAllRow}>
            <Checkbox
              checked={isSelectAllChecked}
              indeterminate={isSelectAllIndeterminate}
              onChange={handleSelectAll}
            />
            <FormControl.Label>{selectionLabel}</FormControl.Label>
          </FormControl>
        )}
      </div>
      <div className={styles.repositoryListContainer}>
        <PickerListBody
          hiddenSelectedCount={normalizedQuery ? hiddenSelectedCount : 0}
          isFiltered={!!normalizedQuery}
          blankMessage={blankView}
          totalItemsCount={totalEligibleRepoCount}
          selectionVariant="multiple"
          items={displayRepos}
          selectedItems={selectedRepos}
          setSelectedItems={handleItemSelectionChange}
          title="Select repositories for code security assessment"
          onRenderItemName={getRepoName}
          onRenderItemLeadingVisual={getRepoIcon}
        />
      </div>
    </div>
  )
}
