import {useCallback, useEffect, useState} from 'react'
import {Button, Banner, Heading, UnderlineNav, ActionList, ActionMenu, IconButton} from '@primer/react'
import {DownloadIcon, KebabHorizontalIcon, SyncIcon} from '@primer/octicons-react'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useSearchParams} from '@github-ui/use-navigate'
import {useQuery} from '@github-ui/react-query'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {isEnterprise} from '@github-ui/runtime-environment'

import {SharedRiskAssessmentPage} from './SharedRiskAssessmentPage'
import {CodeSecurityRiskAssessmentPage} from './CodeSecurityRiskAssessmentPage'
import type {Assessment, CodeSecurityAssessmentPayload, CreateAssessmentParams, Org} from '../types'
import {SecretRiskAssessmentPage} from './SecretRiskAssessmentPage'
import {RunAssessmentDialog} from '../components/shared/RunAssessmentDialog'
import {queries, useCreateAssessmentMutation} from '../api'
import {DEFAULT_ELIGIBILITY, ASSESSMENT_SOURCE} from '../types'
import {MAX_POLLING_RETRIES, DEFAULT_POLL_INTERVAL} from '../constants'
import {updateAssessmentCopilotContext} from '../utils/copilot-chat-helpers'
import {downloadResultsCSVPath, downloadCsraResultsCSVPath} from '../paths'

type AssessmentType = 'code-security' | 'secret-protection'
export type ViewState = 'shared_landing' | 'csra_results' | 'csra_landing' | 'sra_results' | 'sra_landing'
const ASSESSMENT_TYPE_PARAM = 'assessmentType'

export interface RiskAssessmentLandingPayload extends Partial<CodeSecurityAssessmentPayload> {
  view_state: ViewState
  org: Org
  assessment?: Assessment | null
}

function getAssessmentTypeFromSearchParams(searchParams: URLSearchParams, viewState: string): AssessmentType {
  const assessmentType = searchParams.get(ASSESSMENT_TYPE_PARAM)
  switch (assessmentType) {
    case 'secret-protection':
      return 'secret-protection'
    case 'code-security':
      return 'code-security'
    default:
      // No URL param → use view_state to determine default
      return viewState === 'sra_landing' ? 'secret-protection' : 'code-security'
  }
}

export function RiskAssessmentIndex() {
  const {view_state, org, assessment = null} = useRoutePayload<RiskAssessmentLandingPayload>()
  const [searchParams, setSearchParams] = useSearchParams()
  const [isRerunDialogOpen, setIsRerunDialogOpen] = useState(false)
  // CSRA is not available on GHES; force SRA-only UI in that environment.
  const csraHidden = isEnterprise()
  const activeTab = csraHidden ? 'secret-protection' : getAssessmentTypeFromSearchParams(searchParams, view_state)
  const mutation = useCreateAssessmentMutation({org: org.login, source: ASSESSMENT_SOURCE.SHARED_LANDING})
  const {data: eligibility, isLoading: isEligibilityLoading} = useQuery(queries.eligibility(org.login))
  const resolvedEligibility = eligibility ?? DEFAULT_ELIGIBILITY
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  // On GHES, drop any stale ?assessmentType= query param (the CSRA tab is hidden,
  // so the param has no effect and shouldn't linger in the URL).
  useEffect(() => {
    if (csraHidden && searchParams.has(ASSESSMENT_TYPE_PARAM)) {
      const newParams = new URLSearchParams(searchParams)
      newParams.delete(ASSESSMENT_TYPE_PARAM)
      setSearchParams(newParams, {replace: true})
    }
  }, [csraHidden, searchParams, setSearchParams])

  // Update copilot panel suggestions whenever the active tab changes.
  // The reducer's chatIsOpen guard ensures this is a no-op when copilot isn't open.
  useEffect(() => {
    updateAssessmentCopilotContext(activeTab)
  }, [activeTab])

  const handleSelectTab = useCallback(
    (assessmentType: AssessmentType) => () => {
      const newParams = new URLSearchParams(searchParams)
      newParams.set(ASSESSMENT_TYPE_PARAM, assessmentType)
      setSearchParams(newParams)
    },
    [searchParams, setSearchParams],
  )

  const handleRerunScan = (params: CreateAssessmentParams) => {
    sendClickAnalyticsEvent({
      location: 'security-assessment-header',
      category: 'rerun-scan-button',
      action: 'rerun-scan',
      tag: 'button',
    })
    mutation.mutate(params)
  }

  // sra_landing implies CSRA exists (the org ran CSRA first but hasn't run SRA yet)
  const hasExistingCsra = !csraHidden && (view_state === 'csra_results' || view_state === 'sra_landing')

  const {data: csraAssessment} = useQuery({
    ...queries.csraAssessment(org.login),
    enabled: hasExistingCsra,
    staleTime: Infinity,
    refetchInterval: query => {
      if (query.state.errorUpdateCount >= MAX_POLLING_RETRIES) return false
      const status = query.state.data?.status
      if (status === 'completed' || status === 'failed') return false
      return DEFAULT_POLL_INTERVAL
    },
  })

  const hasExistingSra = !!assessment
  const hasCompletedSra = assessment?.is_complete ?? false
  const hasCompletedOrFailedCsra =
    hasExistingCsra && (csraAssessment?.status === 'completed' || csraAssessment?.status === 'failed')

  const showRerunButton = activeTab === 'code-security' ? hasExistingCsra : hasExistingSra
  const showCsvMenu = hasCompletedSra || hasCompletedOrFailedCsra
  // On GHES, the rerun click bypasses the dialog and starts SRA immediately.
  // Disable the button when SRA is in cooldown so we don't trigger a request that
  // the server will reject and surface a generic error banner. Guard against the
  // loading window in case DEFAULT_ELIGIBILITY ever changes its default.
  const rerunDisabledOnGhes = csraHidden && !isEligibilityLoading && !resolvedEligibility.sra.eligible

  switch (view_state) {
    case 'shared_landing':
      if (csraHidden) {
        return <SecretRiskAssessmentPage />
      }
      return <SharedRiskAssessmentPage org={org} hasExistingAssessment={hasExistingCsra} />

    default:
      return (
        <>
          {mutation.isError && (
            <Banner variant="critical" title="Error" description="Failed to rerun scan. Please try again later." />
          )}
          <div className="d-flex flex-justify-between flex-items-center mb-2">
            <Heading as="h2" className="f2 text-normal">
              Security assessments
            </Heading>
            {(showRerunButton || showCsvMenu) && (
              <div className="d-flex flex-items-center gap-2">
                {showRerunButton && (
                  <Button
                    leadingVisual={SyncIcon}
                    disabled={rerunDisabledOnGhes}
                    onClick={() => {
                      if (csraHidden) {
                        // Skip the assessment-selection dialog on GHES; rerun SRA immediately.
                        handleRerunScan({run_sra: true, run_csra: false})
                      } else {
                        setIsRerunDialogOpen(true)
                      }
                    }}
                  >
                    Rerun scan
                  </Button>
                )}
                {showCsvMenu && (
                  <ActionMenu>
                    <ActionMenu.Anchor>
                      <IconButton
                        aria-label="More assessment options"
                        icon={KebabHorizontalIcon}
                        data-testid="assessment-more-options"
                      />
                    </ActionMenu.Anchor>
                    <ActionMenu.Overlay>
                      <ActionList>
                        {hasCompletedSra && (
                          <ActionList.LinkItem
                            href={downloadResultsCSVPath(org.login)}
                            onClick={() => {
                              sendClickAnalyticsEvent({
                                location: 'security-assessment-header',
                                category: 'assessment-results-menu',
                                action: 'download-sra-csv',
                                tag: 'link',
                              })
                            }}
                          >
                            <ActionList.LeadingVisual>
                              <DownloadIcon />
                              {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                            </ActionList.LeadingVisual>
                            Download Secret Risk Assessment CSV
                          </ActionList.LinkItem>
                        )}
                        {hasCompletedOrFailedCsra && (
                          <ActionList.LinkItem
                            href={downloadCsraResultsCSVPath(org.login)}
                            onClick={() => {
                              sendClickAnalyticsEvent({
                                location: 'security-assessment-header',
                                category: 'assessment-results-menu',
                                action: 'download-csra-csv',
                                tag: 'link',
                              })
                            }}
                          >
                            <ActionList.LeadingVisual>
                              <DownloadIcon />
                              {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                            </ActionList.LeadingVisual>
                            Download Code Security Risk Assessment CSV
                          </ActionList.LinkItem>
                        )}
                      </ActionList>
                    </ActionMenu.Overlay>
                  </ActionMenu>
                )}
              </div>
            )}
          </div>

          {!csraHidden && (
            <UnderlineNav aria-label="Security assessment types">
              <UnderlineNav.Item
                as="button"
                aria-current={activeTab === 'code-security' ? 'page' : undefined}
                onSelect={handleSelectTab('code-security')}
              >
                Code Security
              </UnderlineNav.Item>
              <UnderlineNav.Item
                as="button"
                aria-current={activeTab === 'secret-protection' ? 'page' : undefined}
                onSelect={handleSelectTab('secret-protection')}
              >
                Secret Protection
              </UnderlineNav.Item>
            </UnderlineNav>
          )}

          <div className="tmp-mt-3">
            {activeTab === 'code-security' && !csraHidden ? (
              <CodeSecurityRiskAssessmentPage org={org} hasExistingAssessment={hasExistingCsra} />
            ) : (
              <SecretRiskAssessmentPage />
            )}
          </div>

          {isRerunDialogOpen && !csraHidden && (
            <RunAssessmentDialog
              onClose={() => setIsRerunDialogOpen(false)}
              onStartScan={handleRerunScan}
              org={org}
              source={ASSESSMENT_SOURCE.SHARED_LANDING}
              eligibility={resolvedEligibility}
            />
          )}
        </>
      )
  }
}
