import type {ReactNode} from 'react'
import {useState} from 'react'
import {Banner} from '@primer/react'
import {useClickAnalytics} from '@github-ui/use-analytics'

export function ScanInProgressBanner({
  analyticsLocation,
  description,
  icon,
  analyticsVisible,
}: {
  analyticsLocation: string
  description?: ReactNode
  icon?: ReactNode
  analyticsVisible?: Record<string, string>
}) {
  const [isOpen, setIsOpen] = useState(true)
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  return (
    isOpen && (
      <Banner
        title="Scan in progress, we'll email you when it's ready."
        data-analytics-visible={analyticsVisible ? JSON.stringify(analyticsVisible) : undefined}
        description={description}
        icon={icon}
        variant="info"
        onDismiss={() => {
          setIsOpen(false)
          sendClickAnalyticsEvent({
            location: analyticsLocation,
            category: 'scan-in-progress-banner',
            action: 'dismiss',
            tag: 'icon',
            group: 'expand',
          })
        }}
      />
    )
  )
}
