import {ActionList, ActionMenu} from '@primer/react'

export function CalculatorButtons({
  setIsEnablementDialogOpen,
  setIsROICalculatorOpen,
  sendClickAnalyticsEvent,
  buttonVariant,
}: {
  setIsEnablementDialogOpen: (open: boolean) => void
  setIsROICalculatorOpen: (open: boolean) => void
  sendClickAnalyticsEvent: (event: {
    location: string
    category: string
    action: string
    group?: string
    tag?: string
  }) => void
  buttonVariant?: React.ComponentProps<typeof ActionMenu.Button>['variant']
}) {
  return (
    <div className="d-flex flex-items-center gap-3">
      <ActionMenu>
        <ActionMenu.Button data-testid="calculator-get-started-button" variant={buttonVariant}>
          Enable
        </ActionMenu.Button>
        <ActionMenu.Overlay width="medium">
          <ActionList>
            <ActionList.Item
              onSelect={() => {
                setIsEnablementDialogOpen(true)
                sendClickAnalyticsEvent({
                  location: 'security-assessment-post-scan',
                  category: 'results-banner',
                  action: 'open-enablement-dialog',
                  group: 'expand',
                })
              }}
            >
              Enable Secret Protection
            </ActionList.Item>
            <ActionList.Item
              onSelect={() => {
                setIsROICalculatorOpen(true)
                sendClickAnalyticsEvent({
                  location: 'security-assessment-post-scan',
                  category: 'results-banner',
                  action: 'roi-calculator',
                  group: 'expand',
                })
              }}
            >
              Estimate push protection savings
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </div>
  )
}
