import {useRoutePayload} from '@github-ui/react-core/use-route-payload'

import type {GhasTrial} from '../types'

interface PayloadWithGhasTrial {
  ghas_trial?: GhasTrial
}

/**
 * Returns trial-related state for the post-assessment enablement banners.
 * `canStartTrial` is true when the server-provided `ghas_trial.can_start_trial`
 * is true. The server only includes the `ghas_trial` payload when the
 * `risk_assessment_ghas_trial` feature flag is enabled, so no client-side flag
 * check is needed.
 */
export function useGhasTrial() {
  const {ghas_trial: ghasTrial} = useRoutePayload<PayloadWithGhasTrial>()

  const canStartTrial = Boolean(ghasTrial?.can_start_trial)

  return {ghasTrial, canStartTrial}
}
