import {RepositorySelectionGroup} from './RepositorySelectionGroup'
import type {CostDisplayValues, Org, RepoSelection} from '../../../types'
import {CostSummaryBox} from './CostSummaryBox'
import {Banner} from '@primer/react'

interface CostEstimationProps {
  totalCostDisplay: string
  repoSelection: RepoSelection
  onRepoSelectionChange: (selection: RepoSelection) => void
  isEnterpriseOrMT?: boolean
  org: Org
  isSecretProtection: boolean
  productName: string
  costDisplayValues: CostDisplayValues
}

export function CostEstimation({
  totalCostDisplay,
  repoSelection,
  onRepoSelectionChange,
  isEnterpriseOrMT = false,
  org,
  isSecretProtection,
  productName,
  costDisplayValues,
}: CostEstimationProps) {
  const {licenseCount, repositoryCountText, perLicenseCost} = costDisplayValues

  const trialKey = isSecretProtection ? 'secret_protection_trial' : 'code_security_trial'
  const isOnTrial = org.active_ghas_trials?.includes(trialKey)
  const trialExpirationDate = org.active_ghas_trials_expiration?.[trialKey]

  return (
    <>
      {isOnTrial && trialExpirationDate && (
        <Banner
          title="Info"
          hideTitle
          description={`You are currently on a GitHub ${productName} trial until ${trialExpirationDate}. No charges will be incurred during that trial.`}
          className="tmp-mb-3"
        />
      )}
      <p>
        <span>{productName} is </span>
        {!isEnterpriseOrMT && <span>free for public repositories and </span>}
        <span>billed per active committer for private repositories.</span>
      </p>
      {isSecretProtection && <p>Estimate your monthly cost based on selection.</p>}
      {!isSecretProtection && <p>Enable in:</p>}

      <RepositorySelectionGroup value={repoSelection} onChange={onRepoSelectionChange} />

      {(isSecretProtection || org.is_ghas_metered) && (
        <CostSummaryBox
          totalCostDisplay={totalCostDisplay}
          licenseCount={licenseCount}
          repositoryCountText={repositoryCountText}
          perLicenseCost={perLicenseCost}
          productName={productName}
        />
      )}
    </>
  )
}
