import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import {Dialog} from '@primer/react'

import {REPO_SELECTION} from '../../constants'
import {RepositorySelection} from './EnablementDialog/RepositorySelection'
import {CostEstimation} from './EnablementDialog/CostEstimation'
import {useEnablementMutations} from '../../hooks/use-enablement-mutations'
import {useDialogNavigation} from '../../hooks/use-dialog-navigation'
import {useFilterState} from '../../hooks/use-filter-state'
import {useRepositoryData} from '../../hooks/use-repository-data'
import {Footer} from './EnablementDialog/Footer'
import {Title} from './EnablementDialog/Title'
import type {Cost, EnablementRepo, EnablementDialogContext, EnablementSuccess, Org} from '../../types'
import {getCostDisplayValues} from '../../utils/enablement-dialog-utils'
import styles from './EnablementDialog/EnablementDialog.module.css'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {Review} from './EnablementDialog/Review'

interface EnablementDialogProps {
  isOpen: boolean
  onClose: () => void
  cost: Cost
  org: Org
  handleEnablement: (payload: EnablementSuccess) => void
  assessmentNumber: number
  assessmentDate?: string
  isEnterpriseOrMT?: boolean
  context: EnablementDialogContext
}

export function EnablementDialog({
  isOpen,
  onClose,
  cost,
  org,
  handleEnablement,
  assessmentNumber,
  assessmentDate,
  isEnterpriseOrMT = false,
  context,
}: EnablementDialogProps) {
  const productName = context === 'secret-protection' ? 'Secret Protection' : 'Code Security'
  const isSecretProtection = context === 'secret-protection'
  const analyticsCategory = isSecretProtection ? 'sp-enablement-dialog' : 'cs-enablement-dialog'
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const {
    repoSelection,
    setRepoSelection,
    currentStep,
    isTransitioning,
    handleBackClick,
    handleSelectRepositoriesClick,
    handleReviewAndEnableClick,
    resetNavigation,
  } = useDialogNavigation()

  const {filterValue, debouncedFilterValue, handleFilterSubmit, handleFilterChange, resetFilter} = useFilterState({
    analyticsCategory,
  })

  const [selectedRepoIds, setSelectedRepoIds] = useState<Set<number>>(() => new Set())

  const {reposById, allCachedReposById, totalRepoCount, isLoading, isError, resetPreSelection, applyPreSelection} =
    useRepositoryData({
      orgLogin: org.login,
      assessmentNumber,
      isOpen,
      isSecretProtection,
      repoSelection,
      debouncedFilterValue,
    })

  const resetDialogState = useCallback(() => {
    resetNavigation()
    resetFilter()
    setSelectedRepoIds(new Set())
    resetPreSelection()
  }, [resetNavigation, resetFilter, resetPreSelection])

  const sendCloseAnalytics = useCallback(() => {
    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: analyticsCategory,
      action: 'close',
    })
  }, [sendClickAnalyticsEvent, analyticsCategory])

  const {isMutating, handleEnableClick} = useEnablementMutations({
    orgLogin: org.login,
    assessmentNumber,
    isSecretProtection,
    repoSelection,
    selectedRepoIds,
    handleEnablement,
    handleCloseDialog: () => {
      resetDialogState()
      onClose()
      sendCloseAnalytics()
    },
    analyticsCategory,
  })

  const handleCloseDialog = () => {
    resetDialogState()
    onClose()
    sendCloseAnalytics()
  }

  // Auto-select CSRA repos on first data load
  useEffect(() => {
    applyPreSelection(setSelectedRepoIds)
  }, [applyPreSelection])

  // Reset pre-selection when the dialog is closed externally
  const prevIsOpenRef = useRef(isOpen)
  useEffect(() => {
    if (prevIsOpenRef.current && !isOpen) {
      resetPreSelection()
    }
    prevIsOpenRef.current = isOpen
  }, [isOpen, resetPreSelection])

  const selectedCommitterIds = useMemo(() => {
    const memo = new Set<number>()
    for (const repoId of selectedRepoIds) {
      const repo = allCachedReposById.get(repoId)
      const committerIds = repo?.additionalCommitterIds || []
      for (const committerId of committerIds) memo.add(committerId)
    }
    return memo
  }, [allCachedReposById, selectedRepoIds])

  const onChangeSelectedRepos = (selectedRepos: EnablementRepo[]) => {
    setSelectedRepoIds(prev => {
      const next = new Set(prev)
      for (const repoId of reposById.keys()) next.delete(repoId)
      for (const selectedRepo of selectedRepos) next.add(selectedRepo.id)
      return next
    })
  }

  const {totalCost, licenseCount} = useMemo(() => {
    const perLicenseAmount = parseFloat(cost.per_license.replace(/[$,]/g, ''))
    const total = selectedCommitterIds.size * perLicenseAmount
    return {
      totalCost: total.toLocaleString('en-US', {style: 'currency', currency: 'USD'}),
      licenseCount: selectedCommitterIds.size,
    }
  }, [cost.per_license, selectedCommitterIds.size])

  const totalCostDisplay = repoSelection === REPO_SELECTION.ALL ? cost.total : totalCost
  const displayLicenseCount = repoSelection === REPO_SELECTION.ALL ? cost.increased_license_usage : licenseCount
  const costDisplayValues = getCostDisplayValues(repoSelection, cost, displayLicenseCount, selectedRepoIds.size)

  const getFooterProps = () => {
    const costSummary = isSecretProtection ? {totalCost, licenseCount, productName} : undefined

    switch (currentStep) {
      case 'repository-selection':
        return {
          primaryLabel: 'Review and enable',
          primaryAction: handleReviewAndEnableClick,
          primaryLoading: isMutating,
          primaryDisabled: repoSelection === REPO_SELECTION.SELECTED && selectedRepoIds.size === 0,
          selectedCount: selectedRepoIds.size,
          costSummary,
        }
      case 'review':
        return {
          primaryLabel: `Enable ${productName}`,
          primaryAction: handleEnableClick,
          primaryLoading: isMutating,
          primaryDisabled: false,
        }
      default:
        if (repoSelection === REPO_SELECTION.SELECTED) {
          return {
            primaryLabel: 'Select repositories',
            primaryAction: handleSelectRepositoriesClick,
            primaryLoading: false,
            primaryDisabled: false,
          }
        }
        return {
          primaryLabel: 'Review and enable',
          primaryAction: handleReviewAndEnableClick,
          primaryLoading: isMutating,
          primaryDisabled: false,
        }
    }
  }

  const renderFooter = () => <Footer onClose={handleCloseDialog} {...getFooterProps()} />

  const renderDialogContent = () => {
    switch (currentStep) {
      case 'repository-selection':
        return (
          <RepositorySelection
            selectedRepoIds={selectedRepoIds}
            onRepositorySelectionChange={onChangeSelectedRepos}
            selectedCommitterIds={selectedCommitterIds}
            reposById={reposById}
            totalRepoCount={totalRepoCount}
            isLoading={isLoading || isTransitioning}
            isError={isError}
            filterValue={filterValue}
            onFilterChange={handleFilterChange}
            onFilterSubmit={handleFilterSubmit}
            orgLogin={org.login}
          />
        )
      case 'review':
        return (
          <Review
            totalCostDisplay={totalCostDisplay}
            org={org.login}
            repoSelection={repoSelection}
            isSecretProtection={isSecretProtection}
            isMetered={org.is_ghas_metered}
            productName={productName}
            costDisplayValues={costDisplayValues}
          />
        )
      case 'cost-estimation':
      default:
        return (
          <CostEstimation
            totalCostDisplay={totalCostDisplay}
            repoSelection={repoSelection}
            onRepoSelectionChange={setRepoSelection}
            isEnterpriseOrMT={isEnterpriseOrMT}
            org={org}
            isSecretProtection={isSecretProtection}
            productName={productName}
            costDisplayValues={costDisplayValues}
          />
        )
    }
  }

  const titleText =
    currentStep === 'repository-selection'
      ? 'Select repositories'
      : currentStep === 'cost-estimation' && isSecretProtection
        ? `Estimate cost of ${productName}`
        : `Enable ${productName}`

  const showBackButton = currentStep !== 'cost-estimation'
  const backAriaLabel = currentStep === 'repository-selection' ? 'Back to cost estimation' : 'Back to previous step'
  const dialogHeight = currentStep === 'repository-selection' ? 'large' : 'auto'

  return (
    isOpen && (
      <Dialog
        onClose={handleCloseDialog}
        height={dialogHeight}
        title={
          <Title text={titleText} onBack={showBackButton ? handleBackClick : undefined} backAriaLabel={backAriaLabel} />
        }
        subtitle={
          currentStep === 'repository-selection' && (
            <div className="tmp-ml-5">
              {isSecretProtection ? (
                <>
                  Showing repositories without Secret Protection. Committers refers to distinct contributors with
                  activity in the past 90 days. Secret count based on <span>{assessmentDate || 'latest'}</span>{' '}
                  assessment.
                </>
              ) : (
                <>
                  Showing all repositories without Code Security enabled. Committers refers to distinct contributors
                  with activity in the past 90 days. Vulnerability count based on latest assessment.
                </>
              )}
            </div>
          )
        }
        renderFooter={renderFooter}
        className={currentStep === 'repository-selection' ? styles.enablementDialog : undefined}
      >
        {renderDialogContent()}
      </Dialog>
    )
  )
}
